#!/usr/bin/env bash
#
# pi-git.sh - create, resume and apply a trial solution generated by the Pi
# coding agent, held in a Git solution branch.

set -euo pipefail

PROG=$(basename "$0")
PROMPT_FILE='PROMPT.md'
LOG_FILE='PI_GIT_LOG.md'

usage() {
    cat <<EOF

USAGE:
  $PROG apply [-m <message>] -b <branch-name>
  $PROG create [-m <message>] [-b <branch-name>] -M <model-name>
  $PROG resume

COMMAND:
  apply    Squash a trial solution branch to the current branch.
  create   Create a trial solution branch from the current branch:
             - Create a new Pi session named <model-id>
             - Execute the prompt in the PROMPT.md file
             - Optionally commit the changes to a new branch pi/<model-id>
  resume   Update a trial solution:
             - Prompt the user to select a Pi session to resume
             - Execute the prompt in the PROMPT.md file

NOTE:
  - The <model-id> is the slugified base component of the <model-name>.
  - The 'resume' command executes the prompt in the PROMPT.md file, it does not commit the changes.
  - 'create' and 'resume' commands append PROMPT.md to the PI_GIT_LOG.md log file.

OPTIONS:
  -h, --help                   Show this help and exit.
  -n, --dry-run                Print the commands without executing them.
  -b, --branch <branch-name>   Trial solution branch (default pi/<model-id>).
  -M, --model <model-name>     Model name (required for create).
  -m, --message <message>      Commit message (create default: "Create trial solution <branch>").

WORKFLOW:
  1. Write a task specification to the PROMPT.md file.
  2. Run the 'create' command to:
     - Generate a trial solution by executing the PROMPT.md prompt with the Pi command.
     - Optionally commit the trial solution to the pi/<model-id> branch (replacing it if it exists).
  3. Review and test the trial solution.
  4. If the solution is unsatisfactory, edit PROMPT.md and run the 'resume' command (repeat if necessary).
  5. Squash the solution branch onto the HEAD of the current branch with the 'apply' command.

EOF
}

die() {
    echo "$PROG: error: $*" >&2
    exit 2
}

# Execute a command, or print it (shell-quoted) in dry-run mode.
run() {
    if [[ $dry_run == true ]]; then
        printf '%q ' "$@"
        printf '\n'
    else
        "$@"
    fi
}

# Ask a yes/no question. $1 is the prompt, $2 the default answer (y or n).
# Return 0 if the answer is yes. In dry-run mode the question is printed and
# the answer is assumed to be yes.
confirm() {
    local reply
    if [[ $dry_run == true ]]; then
        echo "Would prompt: $1"
        return 0
    fi
    read -r -p "$1 " reply || reply=''
    reply=${reply:-$2}
    [[ $reply =~ ^[Yy]$ ]]
}

# Like confirm, but exit if the answer is no.
confirm_or_abort() {
    confirm "$@" || {
        echo "Aborted."
        exit 1
    }
}

# Print the model ID for model name $1: its last '/'-separated component with
# characters that are not allowed in Git branch names replaced by '-'.
model_id_for() {
    local id=${1##*/}
    id=$(printf '%s' "$id" | sed -E 's/[^A-Za-z0-9._-]+/-/g; s/\.\.+/./g; s/^[-.]+//; s/[-.]+$//')
    [[ -n $id ]] || die "cannot derive a model ID from model name: $1"
    printf '%s\n' "$id"
}

# Exit with an error if $1 is not a valid Git branch name.
check_branch_name() {
    git check-ref-format "refs/heads/$1" || die "invalid branch name: $1"
}

# True if the working tree has no changes.
is_clean() {
    [[ -z $(git status --porcelain) ]]
}

# True if the local branch $1 exists.
branch_exists() {
    git show-ref --verify --quiet "refs/heads/$1"
}

# Append a Markdown header and the PROMPT.md contents to the log file.
append_log() {
    local title=$1 header
    header="## $(date '+%Y-%m-%d %H:%M'): $title"

    if [[ $dry_run == true ]]; then
        echo "Would append to $LOG_FILE:"
        echo
        echo "$header"
        echo "<contents of $PROMPT_FILE>"
        echo
    else
        {
            echo
            echo "$header"
            echo
            cat "$PROMPT_FILE"
        } >>"$LOG_FILE"
    fi
}

create_trial() {
    local start elapsed

    echo "----------------------------------------------------------------------"
    echo "$model_id: Creating trial solution..."
    echo "----------------------------------------------------------------------"
    echo
    append_log "$branch: $model_name: $commit_msg"
    start=$SECONDS
    run pi --name "$model_id" --print --model "$model_name" "@$PROMPT_FILE"
    elapsed=$((SECONDS - start))

    echo
    printf 'Time taken: %d:%02d\n' $((elapsed / 60)) $((elapsed % 60))
    echo

    confirm_or_abort "About to create/overwrite branch '$branch' and commit trial solution. Continue? (Y/n):" y
    run git switch -C "$branch"
    run git add -A
    run git commit -m "$commit_msg"
    run git switch "$current_branch"
}

resume_trial() {
    echo "----------------------------------------------------------------------"
    echo "Resuming trial solution on branch '$current_branch'..."
    echo "----------------------------------------------------------------------"
    echo
    append_log "$current_branch: resume"
    run pi --resume "@$PROMPT_FILE"
}

apply_trial() {
    echo "----------------------------------------------------------------------"
    echo "Applying trial solution '$branch'..."
    echo "----------------------------------------------------------------------"
    echo
    run git merge --squash "$branch"
    run git commit -m "$commit_msg"
}

# ---------------------------------------------------------------------------
# Parse arguments
# ---------------------------------------------------------------------------

command=''
branch=''
model_name=''
commit_msg=''
dry_run=false

if [[ $# -eq 0 ]]; then
    usage >&2
    exit 2
fi

while [[ $# -gt 0 ]]; do
    case $1 in
    -h | --help)
        usage
        exit 0
        ;;
    -n | --dry-run)
        dry_run=true
        ;;
    -b | --branch)
        [[ $# -ge 2 && -n $2 ]] || die "option $1 requires a non-empty argument"
        branch=$2
        shift
        ;;
    -M | --model)
        [[ $# -ge 2 && -n $2 ]] || die "option $1 requires a non-empty argument"
        model_name=$2
        shift
        ;;
    -m | --message)
        [[ $# -ge 2 && -n $2 ]] || die "option $1 requires a non-empty argument"
        commit_msg=$2
        shift
        ;;
    -*)
        die "unknown option: $1"
        ;;
    *)
        [[ -z $command ]] || die "unexpected argument: $1"
        command=$1
        ;;
    esac
    shift
done

# ---------------------------------------------------------------------------
# Validate arguments
# ---------------------------------------------------------------------------

case $command in
create | apply | resume) ;;
'') die "missing COMMAND (create, apply or resume)" ;;
*) die "unknown COMMAND: $command (expected create, apply or resume)" ;;
esac

case $command in
create)
    [[ -n $model_name ]] || die "create requires the -M, --model <model-name> option"
    model_id=$(model_id_for "$model_name")
    branch=${branch:-pi/$model_id}
    check_branch_name "$branch"
    commit_msg=${commit_msg:-"Create trial solution $branch"}
    ;;
apply)
    [[ -n $branch ]] || die "apply requires the -b, --branch <branch-name> option"
    [[ -z $model_name ]] || die "-M, --model is not valid with apply"
    check_branch_name "$branch"
    commit_msg=${commit_msg:-"Apply trial solution $branch"}
    ;;
resume)
    [[ -z $branch && -z $model_name && -z $commit_msg ]] ||
        die "resume accepts no -b, -M or -m options"
    ;;
esac

# ---------------------------------------------------------------------------
# Run
# ---------------------------------------------------------------------------

# Work from the top of the Git repository so that @PROMPT.md and the Git
# commands always refer to the same project.
cd "$(git rev-parse --show-toplevel)"
current_branch=$(git branch --show-current)

case $command in
create)
    [[ -n $current_branch ]] || die "HEAD is detached, check out a branch before running the create command"
    [[ $current_branch != "$branch" ]] ||
        die "The current branch and the solution branch ('$branch') cannot be the same."
    is_clean || confirm_or_abort "The working tree is not clean (existing changes will be retained). Continue? (y/N):" n
    [[ -f $PROMPT_FILE ]] || die "$PROMPT_FILE not found"
    create_trial
    ;;
resume)
    is_clean || confirm_or_abort "The working tree is not clean (existing changes will be retained). Continue? (y/N):" n
    [[ -f $PROMPT_FILE ]] || die "$PROMPT_FILE not found"
    resume_trial
    ;;
apply)
    [[ $current_branch != "$branch" ]] ||
        die "The current branch and the solution branch ('$branch') cannot be the same."
    is_clean || die "The working tree is not clean, commit or discard the changes before proceeding."
    branch_exists "$branch" || die "The solution branch '$branch' does not exist."
    apply_trial
    ;;
esac
